</head>
<body>
    <div id="root"></div>

    <script type="text/babel">
        const { useState } = React;

        function ConsentForm() {
            const [agreed, setAgreed] = useState(false);
            const [status, setStatus] = useState(null);

            const handleSubmit = (e) => {
                e.preventDefault();
                if (agreed) {
                    setStatus({ type: 'success', message: 'Thank you for agreeing to the terms!' });
                } else {
                    // This case shouldn't be reachable with 'required' attribute, 
                    // but good for robustness.
                    setStatus({ type: 'error', message: 'You must agree to the terms to continue.' });
                }
            };

            return (
                <main className="container">
                    <h1>Terms of Use</h1>
                    <form onSubmit={handleSubmit} noValidate={false}>
                        <div className="form-field">
                            <div className="checkbox-wrapper" onClick={() => setAgreed(!agreed)}>
                                <input
                                    id="terms-checkbox"
                                    type="checkbox"
                                    required
                                    checked={agreed}
                                    onChange={(e) => setAgreed(e.target.checked)}
                                    aria-describedby="terms-helper"
                                />
                                <label htmlFor="terms-checkbox">
                                    I agree to the Terms of Use
                                    <span className="required-star" aria-hidden="true">*</span>
                                </label>
                            </div>
                            <span id="terms-helper" className="helper-text">
                                Review our terms before proceeding.
                            </span>
                        </div>

                        <button type="submit">
                            Confirm Consent
                        </button>

                        {status && (
                            <div 
                                className={`status-message ${status.type === 'success' ? 'status-success' : 'status-error'}`}
                                role="status"
                                aria-live="polite"
                            >
                                {status.message}
                            </div>
                        )}
                    </form>
                </main>
            );
        }

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<ConsentForm />);
    </script>
</body>
</html>
